// Cloudflare Worker - Food System Ordering
const BASE64_HTML = "";

export default {
  async fetch(request, env, ctx) {
    const html = Uint8Array.from(atob(BASE64_HTML), c => c.charCodeAt(0));
    return new Response(html, {
      headers: {
        'content-type': 'text/html;charset=UTF-8',
        'cache-control': 'public, max-age=300',
      },
    });
  },
};
